// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.27;

import {MAX_TOKENS} from "./../Constants.sol";
import {VertexId} from "./Id.sol";
import {VaultProxy} from "./VaultProxy.sol";
import {VaultLib} from "./VaultProxy.sol";
import {ClosureId} from "../closure/Id.sol";
import {Store} from "../Store.sol";

struct Reserve {
    // The shares we have for the balance we have in each vault.
    uint256[MAX_TOKENS] shares;
}

library ReserveLib {
    ClosureId public constant RESERVEID = ClosureId.wrap(0);
    uint8 public constant SHARE_RESOLUTION = 100;

    /// Deposit into the reserve real amounts and get shares.
    /// @dev We round shares down.
    function deposit(
        VertexId vid,
        uint256 amount
    ) internal returns (uint256 shares) {
        VaultProxy memory vProxy = VaultLib.getProxy(vid);
        shares = deposit(vProxy, vid, amount);
        vProxy.commit();
    }

    /// Deposit into the reserve real amounts for shares with an existing VaultProxy
    function deposit(
        VaultProxy memory vProxy,
        VertexId vid,
        uint256 amount
    ) internal returns (uint256 shares) {
        Reserve storage reserve = Store.reserve();
        uint8 idx = vid.idx();
        uint128 balance = vProxy.balance(RESERVEID, true);
        vProxy.deposit(RESERVEID, amount);
        // If someone tries to share inflate attack this, they'd have to donate to the underlying vault,
        // which then splits the donation across existing deposits from other people using the vault,
        // including the other closures. So there's no way to inflate shares here.
        shares = (balance == 0)
            ? amount * SHARE_RESOLUTION
            : (amount * reserve.shares[idx]) / balance; // No need for mulDiv.
        reserve.shares[idx] += shares;
    }

    /// Query the value of the shares held in the base token in this reserve.
    /// @dev We round down the redeemed value for safety reasons.
    function query(
        VertexId vid,
        uint256 shares
    ) internal view returns (uint256 amount) {
        Reserve storage reserve = Store.reserve();
        uint8 idx = vid.idx();
        if (reserve.shares[idx] == 0) return 0;
        VaultProxy memory vProxy = VaultLib.getProxy(vid);
        uint128 balance = vProxy.balance(RESERVEID, true);
        amount = (shares * balance) / reserve.shares[idx];
    }

    /// Withdraw the redemption value of the given shares to this contract from the vault.
    /// @dev We round down the redeemed value for safety reasons.
    /// @dev Reverts if we cannot withdraw the desired amount.
    function withdraw(
        VertexId vid,
        uint256 shares
    ) internal returns (uint256 amount) {
        Reserve storage reserve = Store.reserve();
        uint8 idx = vid.idx();
        if (reserve.shares[idx] == 0) return 0;
        VaultProxy memory vProxy = VaultLib.getProxy(vid);
        uint128 balance = vProxy.balance(RESERVEID, true);
        amount = (shares * balance) / reserve.shares[idx];
        vProxy.withdraw(RESERVEID, amount);
        vProxy.commit();
        reserve.shares[idx] -= shares;
    }
}

src/multi/vertex/VaultProxy.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.27;

import {VertexId} from "./Id.sol";
import {VaultPointer, VaultType} from "./VaultPointer.sol";
import {VaultE4626} from "./E4626.sol";
import {Store} from "../Store.sol";
import {ClosureId} from "../closure/Id.sol";

// Holds overall vault information.
struct VaultStorage {
    // Vaults in use.
    mapping(VertexId => address vault) vaults;
    // Vaults we're potentially transfering into.
    mapping(VertexId => address vault) backups;
    // Vault info.
    mapping(address vault => VaultType) vTypes;
    mapping(address vault => VaultE4626) e4626s;
    mapping(address vault => VertexId) usedBy;
}

/// Each vertex has a primary vault and a backup vault it may be migrating to.
/// The combination of the two is a VaultProxy.
/// Fetching a VaultProxy and operating on the Vault Storage is done through VaultLib.
library VaultLib {
    // If we have fewer than this many tokens left in a vault, we can remove it.
    uint256 public constant BALANCE_DE_MINIMUS = 10;

    // Thrown when a vault has already been added before.
    error VaultExists(address);
    // Thrown when removing a vault that still holds a substantive balance.
    error RemainingVaultBalance(uint256);
    // This vault type is not currently supported.
    error VaultTypeNotRecognized(VaultType);
    // Thrown during a get if the vault can't be found.
    error VaultNotFound(address);
    // Thrown when there is already a primary and a backup vault.
    error VertexVaultsOccupied(VertexId);
    // Thrown when removing a vault that is still in use.
    error VaultInUse(address, VertexId);
    // Thrown when deleting or swapping a vault but there is no backup for the vertex.
    error NoBackup(VertexId);

    /// Add a vault for a vertex. There needs to at least be one per vertex.
    /// Adds as the primary vault if one does not exist yet, then the backup vault.
    function add(
        VertexId vid,
        address token,
        address vault,
        VaultType vType
    ) internal {
        VaultStorage storage vStore = Store.vaults();
        // First add to vault tracking.
        if (vStore.vaults[vid] == address(0)) {
            // Add as the primary vault
            vStore.vaults[vid] = vault;
        } else if (vStore.backups[vid] == address(0)) {
            // Add as a backup.
            vStore.backups[vid] = vault;
        } else {
            revert VertexVaultsOccupied(vid);
        }

        // Now add vault details.
        if (vStore.vTypes[vault] != VaultType.UnImplemented)
            revert VaultExists(vault);
        vStore.vTypes[vault] = vType;
        if (vType == VaultType.E4626) vStore.e4626s[vault].init(token, vault);
        else revert VaultTypeNotRecognized(vType);
        vStore.usedBy[vault] = vid;
    }

    function remove(address vault) internal {
        VaultPointer memory vPtr = getVault(vault);
        uint256 outstanding = vPtr.totalBalance(false);
        if (outstanding > BALANCE_DE_MINIMUS)
            revert RemainingVaultBalance(outstanding);

        VaultStorage storage vStore = Store.vaults();
        VertexId vid = vStore.usedBy[vault];
        if (vStore.vaults[vid] == vault) revert VaultInUse(vault, vid);

        // We are not the active vault, so we're the backup and we have no tokens. Okay to remove.
        delete vStore.backups[vid];

        VaultType vType = vStore.vTypes[vault];
        delete vStore.vTypes[vault];
        // Vault specific operation.
        if (vType == VaultType.E4626) vStore.e4626s[vault].del();
        else revert VaultTypeNotRecognized(vType);
        // VertexId delete.
        vStore.usedBy[vault] = VertexId.wrap(0);
    }

    /// Move an amount of tokens from one vault to another.
    /// @dev This implicitly requires that the two vaults are based on the same token
    /// and there can only be two vaults for a given token.
    function transfer(
        address fromVault,
        address toVault,
        ClosureId cid,
        uint256 amount
    ) internal {
        VaultPointer memory from = getVault(fromVault);
        from.withdraw(cid, amount);
        from.commit();
        VaultPointer memory to = getVault(toVault);
        to.deposit(cid, amount);
        to.commit();
    }

    /// Swap the active vault we deposit into.
    function hotSwap(
        VertexId vid
    ) internal returns (address fromVault, address toVault) {
        VaultStorage storage vStore = Store.vaults();
        // If there is no backup, then we can't do this.
        if (vStore.backups[vid] == address(0)) revert NoBackup(vid);
        // Swap.
        address active = vStore.vaults[vid];
        address backup = vStore.backups[vid];
        vStore.vaults[vid] = backup;
        vStore.backups[vid] = active;
        return (active, backup);
    }

    /* Getters */

    /// Get the active and backup addresses for a vault.
    function getVaultAddresses(
        VertexId vid
    ) internal view returns (address active, address backup) {
        VaultStorage storage vStore = Store.vaults();
        active = vStore.vaults[vid];
        backup = vStore.backups[vid];
    }

    /// Fetch a VaultProxy for the vertex's active vaults.
    function getProxy(
        VertexId vid
    ) internal view returns (VaultProxy memory vProxy) {
        VaultStorage storage vStore = Store.vaults();
        vProxy.active = getVault(vStore.vaults[vid]);
        address backup = vStore.backups[vid];
        if (backup != address(0)) vProxy.backup = getVault(backup);
    }

    /// Fetch a Vault
    function getVault(
        address vault
    ) internal view returns (VaultPointer memory vPtr) {
        VaultStorage storage vStore = Store.vaults();
        vPtr.vType = vStore.vTypes[vault];
        if (vPtr.vType == VaultType.E4626) {
            VaultE4626 storage v = vStore.e4626s[vault];
            assembly {
                mstore(vPtr, v.slot) // slotAddress is the first field.
            }
            v.fetch(vPtr.temp);
        } else {
            revert VaultNotFound(vault);
        }
    }
}

// An in-memory struct used by vertices to interact with vaults.
struct VaultProxy {
    VaultPointer active;
    VaultPointer backup;
}

using VaultProxyImpl for VaultProxy global;

library VaultProxyImpl {
    error VaultTypeUnrecognized(VaultType);
    error WithdrawLimited(ClosureId cid, uint256 requested, uint256 available);

    /// We simply deposit into the active vault pointer.
    function deposit(
        VaultProxy memory self,
        ClosureId cid,
        uint256 amount
    ) internal {
        self.active.deposit(cid, amount);
    }

    /// Withdraw from the active vault, and then the backup if we can't fulfill it entirely.
    function withdraw(
        VaultProxy memory self,
        ClosureId cid,
        uint256 amount
    ) internal {
        // We effectively don't allow withdraws beyond uint128 due to the capping in balance.
        uint128 available = self.active.balance(cid, false);
        uint256 maxWithdrawable = self.active.withdrawable();
        if (maxWithdrawable < available) available = uint128(maxWithdrawable);

        if (amount > available) {
            self.active.withdraw(cid, available);
            uint256 residual = amount - available;
            uint256 backWithdrawable = self.backup.withdrawable();
            if (backWithdrawable < residual) {
                revert WithdrawLimited(
                    cid,
                    amount,
                    backWithdrawable + available
                );
            }
            self.backup.withdraw(cid, residual);
        } else {
            self.active.withdraw(cid, amount);
        }
    }

    /// We withdraw from the active vault regardless of what's available.
    /// If it is blocked it's okay because the expectation is that you're deposting back before
    /// the next vault commit so no funds are actually withdrawn.
    /// @return potent If the withdraw can actually be done or not.
    function nilpotentWithdraw(
        VaultProxy memory self,
        ClosureId cid,
        uint256 amount
    ) internal returns (bool potent) {
        uint128 available = self.active.balance(cid, false);
        uint256 maxWithdrawable = self.active.withdrawable();
        if (maxWithdrawable < available) available = uint128(maxWithdrawable);

        potent = amount <= available;
        // This will succeed for now, but fail on commit if the funds are not returned and withdraws are limited.
        self.active.withdraw(cid, amount);
    }

    /// How much can we withdraw from the vaults right now?
    function withdrawable(
        VaultProxy memory self
    ) internal view returns (uint256 _withdrawable) {
        return self.active.withdrawable() + self.backup.withdrawable();
    }

    /// Query the balance available to the given cid.
    function balance(
        VaultProxy memory self,
        ClosureId cid,
        bool roundUp
    ) internal view returns (uint128 amount) {
        return
            self.active.balance(cid, roundUp) +
            self.backup.balance(cid, roundUp);
    }

    /// Query the total balance of all the given cids.
    function totalBalance(
        VaultProxy memory self,
        ClosureId[] storage cids,
        bool roundUp
    ) internal view returns (uint128 amount) {
        return
            self.active.totalBalance(cids, roundUp) +
            self.backup.totalBalance(cids, roundUp);
    }

    /// Query the total balance of everything.
    function totalBalance(
        VaultProxy memory self,
        bool roundUp
    ) internal view returns (uint256 amount) {
        return
            self.active.totalBalance(roundUp) +
            self.backup.totalBalance(roundUp);
    }

    /// Because vaults batch operations together, they do one final operation
    /// as needed during the commit step.
    function commit(VaultProxy memory self) internal {
        self.active.commit();
        self.backup.commit();
    }

    function isValid(VaultProxy memory self) internal view returns (bool) {
        return self.active.isValid() && self.backup.isValid();
    }

    /// A convenience function that forces a commit and re-fetches from the underlying vault.
    function refresh(VaultProxy memory self) internal {
        self.active.refresh();
        self.backup.refresh();
    }
}

src/multi/vertex/Vertex.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.27;

import {VertexId, VertexLib} from "./Id.sol";
import {ReserveLib} from "./Reserve.sol";

import {VaultType} from "./VaultPointer.sol";
import {VaultLib, VaultProxy} from "./VaultProxy.sol";
import {ClosureId} from "../closure/Id.sol";
import {SimplexLib} from "../Simplex.sol";
import {FullMath} from "../../FullMath.sol";

/**
 * Vertices supply tokens to the closures. Each tracks the total balance of one token.
 * Vertices work in real balances.
 */
struct Vertex {
    VertexId vid;
    bool _isLocked;
}

using VertexImpl for Vertex global;

library VertexImpl {
    /// Minimum balance difference for a trim.
    uint256 public constant MIN_TRIM = 100;

    /// Thrown when a vertex is locked so it cannot accept more deposits, or swaps out.
    error VertexLocked(VertexId vid);
    /// Emitted when the pool is holding insufficient balance for a token.
    /// This should never happen unless something is really wrong, like a vault
    /// losing money. In such an event check what is wrong, the severity, and either
    /// top up the pool or lock the vertex until resolved.
    /// @dev We don't revert because the swap is not the issue and wouldn't resolve
    /// the underlying problem.
    event InsufficientBalance(
        VertexId vid,
        ClosureId cid,
        uint256 targetReal,
        uint256 realBalance
    );

    /* Admin */

    function init(
        Vertex storage self,
        VertexId vid,
        address token,
        address vault,
        VaultType vType
    ) internal {
        self.vid = vid;
        VaultLib.add(self.vid, token, vault, vType);
    }

    /* Closure Operations */

    /// Closures call this before operating on any Vertex. Called on all vertices in a closure when value changes.
    /// Like an overgrown lawn, we typically have more tokens than needed for a given closure.
    /// Given the target REAL balance, we move shares to the reserve and
    /// return the shares moved so the closure can add it as earnings to its depositors.
    /// @dev The shares earned are MOVED TO THE RESERVE.
    /// @param targetReal The amount of tokens the cid expects to have in this token.
    /// @return reserveSharesEarned - The amount of shares moved to the reserve for non-bgt values to claim later.
    /// @return bgtEarned - The amount of bgt earned by the bgt values from exchanging.
    /// @return unspentShares - The amount of reserve shares for earnings not spent in the bgt exchange.
    function trimBalance(
        Vertex storage self,
        ClosureId cid,
        uint256 targetReal,
        uint256 value,
        uint256 bgtValue
    )
        internal
        returns (
            uint256 reserveSharesEarned,
            uint256 bgtEarned,
            uint256 unspentShares
        )
    {
        VaultProxy memory vProxy = VaultLib.getProxy(self.vid);
        uint256 realBalance = vProxy.balance(cid, false);
        // We don't error and instead emit in this scenario because clearly the vault is not working properly but if
        // we error users can't withdraw funds. Instead the right response is to lock and move vaults immediately.
        if (targetReal > realBalance) {
            emit InsufficientBalance(self.vid, cid, targetReal, realBalance);
            return (0, 0, 0);
        }
        uint256 residualReal = realBalance - targetReal;
        // We don't compound when the residual is small as rounding will inflate reserve share balances.
        if (residualReal < MIN_TRIM) {
            return (0, 0, 0);
        }

        uint256 bgtResidual = FullMath.mulDiv(residualReal, bgtValue, value);

        // Now we try to move the shares from the cid vault to the reserve.
        // This is the one place where if the withdraw is limited, it's okay because we don't want
        // deposits to fail. We proceed as normal but make sure the return the funds (through reserves)
        // before the commit.
        bool withdrawPossible = vProxy.nilpotentWithdraw(cid, residualReal);
        reserveSharesEarned = ReserveLib.deposit(
            vProxy,
            self.vid,
            residualReal - bgtResidual
        );
        if (bgtResidual > 0) {
            if (withdrawPossible) {
                // We withdrew the full amount, we can bgt exchange.
                uint256 unspent;
                (bgtEarned, unspent) = SimplexLib.viewBgtExchange(
                    self.vid.idx(),
                    bgtResidual
                );
                unspentShares = ReserveLib.deposit(vProxy, self.vid, unspent);
            } else {
                // We can't bgt exchange because we need to return the withdrawn balance back to the vault
                // through reserves.
                unspentShares = ReserveLib.deposit(
                    vProxy,
                    self.vid,
                    bgtResidual
                );
            }
        }

        vProxy.commit();
        if (bgtEarned > 0) {
            // Now that we've commited we have the tokens to exchange.
            SimplexLib.bgtExchange(self.vid.idx(), bgtResidual);
        }
    }

    /// A few version of trim that just returns the real balances earned.
    function viewTrim(
        Vertex storage self,
        ClosureId cid,
        uint256 targetReal,
        uint256 value,
        uint256 bgtValue
    )
        internal
        view
        returns (uint256 realTokensEarned, uint256 bgtRealResidual)
    {
        VaultProxy memory vProxy = VaultLib.getProxy(self.vid);
        uint256 realBalance = vProxy.balance(cid, false);
        if (targetReal > realBalance) {
            return (0, 0);
        }
        uint256 residualReal = realBalance - targetReal;
        bgtRealResidual = FullMath.mulDiv(residualReal, bgtValue, value);
        realTokensEarned = residualReal - bgtRealResidual;
    }

    /// Closures deposit a real amount into this Vertex.
    function deposit(
        Vertex storage self,
        ClosureId cid,
        uint256 amount
    ) internal {
        VaultProxy memory vProxy = VaultLib.getProxy(self.vid);
        validateLock(self, vProxy);
        vProxy.deposit(cid, amount);
        vProxy.commit();
    }

    /// A barebones version of deposit that does not handle vproxy commit timing or lock checks.
    /// @dev Used by admin functions that have to deposit into multiple closures at once.
    function deposit(
        Vertex storage, // Not needed but conforms to the interface.
        VaultProxy memory vProxy,
        ClosureId cid,
        uint256 amount
    ) internal {
        vProxy.deposit(cid, amount);
    }

    /// Withdraw a specified amount from the holdings of a given closure.
    /// @dev If checkLock is true, it will revert if the vertex is locked.
    /// @dev If the withdraw is limited by withdraw limits, it will revert.
    function withdraw(
        Vertex storage self,
        ClosureId cid,
        uint256 amount,
        bool checkLock
    ) internal {
        VaultProxy memory vProxy = VaultLib.getProxy(self.vid);
        if (checkLock) {
            validateLock(self, vProxy);
        }
        vProxy.withdraw(cid, amount);
        vProxy.commit();
    }

    /// Returns the token balance of a closure.
    function balance(
        Vertex storage self,
        ClosureId cid,
        bool roundUp
    ) internal view returns (uint256 amount) {
        VaultProxy memory vProxy = VaultLib.getProxy(self.vid);
        amount = vProxy.balance(cid, roundUp);
        // Nothing to commit.
    }

    /* Lock operations */

    function lock(Vertex storage self) internal {
        self._isLocked = true;
    }

    function unlock(Vertex storage self) internal {
        self._isLocked = false;
    }

    function isLocked(Vertex storage self) internal view returns (bool) {
        return self._isLocked;
    }

    function validateLock(
        Vertex storage self,
        VaultProxy memory vProxy
    ) internal {
        if (!vProxy.isValid()) lock(self);
        require(!self._isLocked, VertexLocked(self.vid));
    }
}

